void RenderMessageFilterAsyncWaiter::GenerateSingleFrameRoutingInfo(
    FrameRoutingInfoPtr* out_info) {
  base::RunLoop loop;
  proxy_->GenerateSingleFrameRoutingInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             FrameRoutingInfoPtr* out_info
,
             FrameRoutingInfoPtr info) {*out_info = std::move(info);
            loop->Quit();
          },
          &loop,
          out_info));
  loop.Run();
}

